  CONSTRAINT fk_organisation_identifier_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_identifier_country_id FOREIGN KEY (country_id) REFERENCES country (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_identifier_tax_id_type_id FOREIGN KEY (tax_id_type_id) REFERENCES tax_id_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_identifier_verification_status_id FOREIGN KEY (verification_status_id) REFERENCES verification_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_organisation_identifier_country_id_tax_id_type_id_value_lookup_hash (country_id, tax_id_type_id, value_lookup_hash) WHERE deleted_at IS NULL,
  UNIQUE INDEX uq_organisation_identifier_organisation_id_tax_id_type_id (organisation_id, country_id, tax_id_type_id) WHERE deleted_at IS NULL,
  UNIQUE INDEX uq_organisation_identifier_organisation_id_primary (organisation_id, country_id) WHERE is_primary AND deleted_at IS NULL,
  INDEX idx_organisation_identifier_tax_id_type_id (tax_id_type_id),
  INDEX idx_organisation_identifier_verification_status_id (verification_status_id)
);
