CREATE TABLE IF NOT EXISTS organisation_location (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  organisation_id UUID NOT NULL,
  location_label STRING(120) NOT NULL,
  address_type_id UUID NOT NULL,
  is_headquarters BOOL NOT NULL DEFAULT false,
  address_line1 STRING(200) NOT NULL,
  address_line2 STRING(200),
  locality STRING(120),
  city_id UUID NOT NULL,
  state_region_id UUID,
  country_id UUID NOT NULL,
  postal_code STRING(20),
  latitude DECIMAL(9,6),
  longitude DECIMAL(9,6),
  geo_source_id UUID,
  place_ref STRING(120),
  time_zone STRING(64),
  headcount INT4,
  opened_date DATE,
  closed_date DATE,
  CONSTRAINT pk_organisation_location PRIMARY KEY (id),
  CONSTRAINT uq_organisation_location_organisation_id_id UNIQUE (organisation_id, id),
  CONSTRAINT ck_organisation_location_latitude_range CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),
  CONSTRAINT ck_organisation_location_longitude_range CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180),
  CONSTRAINT ck_organisation_location_coordinates_pair CHECK ((latitude IS NULL) = (longitude IS NULL) AND (latitude IS NULL OR geo_source_id IS NOT NULL)),
  CONSTRAINT ck_organisation_location_closed_after_opened CHECK (closed_date IS NULL OR opened_date IS NULL OR closed_date >= opened_date),
  CONSTRAINT fk_organisation_location_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_location_address_type_id FOREIGN KEY (address_type_id) REFERENCES address_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_location_city_id FOREIGN KEY (city_id) REFERENCES city (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_location_state_region_id FOREIGN KEY (state_region_id) REFERENCES state_region (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_location_country_id FOREIGN KEY (country_id) REFERENCES country (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_location_geo_source_id FOREIGN KEY (geo_source_id) REFERENCES geo_source (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_organisation_location_organisation_id (organisation_id) WHERE is_headquarters AND deleted_at IS NULL,
  INDEX idx_organisation_location_city_id_organisation_id (city_id, organisation_id) WHERE deleted_at IS NULL,
  INDEX idx_organisation_location_address_type_id (address_type_id),
  INDEX idx_organisation_location_state_region_id (state_region_id),
  INDEX idx_organisation_location_country_id (country_id),
  INDEX idx_organisation_location_geo_source_id (geo_source_id)
);
