CREATE TABLE IF NOT EXISTS organisation_merge (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  survivor_organisation_id UUID NOT NULL,
  merged_organisation_id UUID NOT NULL,
  merge_status_id UUID NOT NULL,
  match_score DECIMAL(5,2),
  match_basis JSONB,
  reason STRING(300),
  approved_by_app_user_id UUID,
  approved_at TIMESTAMPTZ,
  executed_at TIMESTAMPTZ,
  rolled_back_at TIMESTAMPTZ,
  repoint_map JSONB,
  CONSTRAINT pk_organisation_merge PRIMARY KEY (id),
  CONSTRAINT ck_organisation_merge_distinct_organisations CHECK (survivor_organisation_id <> merged_organisation_id),
  CONSTRAINT ck_organisation_merge_match_score_range CHECK (match_score IS NULL OR match_score BETWEEN 0 AND 100),
  CONSTRAINT ck_organisation_merge_execution_order CHECK (executed_at IS NULL OR approved_at IS NOT NULL),
  CONSTRAINT uq_organisation_merge_merged_organisation_id_survivor_organisation_id UNIQUE (merged_organisation_id, survivor_organisation_id),
  CONSTRAINT fk_organisation_merge_survivor_organisation_id FOREIGN KEY (survivor_organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_merge_merged_organisation_id FOREIGN KEY (merged_organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_merge_merge_status_id FOREIGN KEY (merge_status_id) REFERENCES merge_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_organisation_merge_merged_organisation_id (merged_organisation_id) WHERE executed_at IS NOT NULL AND rolled_back_at IS NULL,
  INDEX idx_organisation_merge_survivor_organisation_id (survivor_organisation_id, merge_status_id),
  INDEX idx_organisation_merge_merge_status_id (merge_status_id),
  INDEX idx_organisation_merge_approved_by_app_user_id (approved_by_app_user_id)
);
