  CONSTRAINT ck_organisation_rating_summary_avg_range CHECK (rating_overall_avg IS NULL OR rating_overall_avg BETWEEN 1 AND 5),
  CONSTRAINT ck_organisation_rating_summary_recommend_range CHECK (recommend_ratio IS NULL OR recommend_ratio BETWEEN 0 AND 100),
