CREATE TABLE IF NOT EXISTS organisation_review (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  organisation_id UUID NOT NULL,
  reviewer_app_user_id UUID,
  reviewer_relation_id UUID NOT NULL,
  employment_type_id UUID,
  job_role_id UUID,
  organisation_location_id UUID,
  rating_overall INT2 NOT NULL,
  rating_culture INT2,
  rating_work_life INT2,
  rating_compensation INT2,
  rating_management INT2,
  rating_career INT2,
  recommendation_answer_id UUID NOT NULL,
  title STRING(200) NOT NULL,
  pros STRING NOT NULL,
  cons STRING NOT NULL,
  advice_to_management STRING,
  language_id UUID,
  tenure_months INT2,
  is_anonymous BOOL NOT NULL DEFAULT true,
  is_employment_verified BOOL NOT NULL DEFAULT false,
  moderation_status_id UUID NOT NULL,
  is_published BOOL NOT NULL DEFAULT false,
  published_at TIMESTAMPTZ,
  helpful_count INT4 NOT NULL DEFAULT 0,
  CONSTRAINT pk_organisation_review PRIMARY KEY (id),
  CONSTRAINT uq_organisation_review_organisation_id_id UNIQUE (organisation_id, id),
  CONSTRAINT ck_organisation_review_rating_overall_range CHECK (rating_overall BETWEEN 1 AND 5),
  CONSTRAINT ck_organisation_review_rating_dimensions_range CHECK ((rating_culture IS NULL OR rating_culture BETWEEN 1 AND 5) AND (rating_work_life IS NULL OR rating_work_life BETWEEN 1 AND 5) AND (rating_compensation IS NULL OR rating_compensation BETWEEN 1 AND 5) AND (rating_management IS NULL OR rating_management BETWEEN 1 AND 5) AND (rating_career IS NULL OR rating_career BETWEEN 1 AND 5)),
  CONSTRAINT ck_organisation_review_tenure_range CHECK (tenure_months IS NULL OR tenure_months BETWEEN 0 AND 720),
  CONSTRAINT ck_organisation_review_published_pair CHECK (is_published = (published_at IS NOT NULL)),
  CONSTRAINT fk_organisation_review_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_review_reviewer_relation_id FOREIGN KEY (reviewer_relation_id) REFERENCES reviewer_relation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_review_employment_type_id FOREIGN KEY (employment_type_id) REFERENCES employment_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_review_job_role_id FOREIGN KEY (job_role_id) REFERENCES job_role (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_review_recommendation_answer_id FOREIGN KEY (recommendation_answer_id) REFERENCES recommendation_answer (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_review_language_id FOREIGN KEY (language_id) REFERENCES language (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_review_moderation_status_id FOREIGN KEY (moderation_status_id) REFERENCES moderation_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_review_location_same_org FOREIGN KEY (organisation_id, organisation_location_id) REFERENCES organisation_location (organisation_id, id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_organisation_review_organisation_id_reviewer_app_user_id_reviewer_relation_id (organisation_id, reviewer_app_user_id, reviewer_relation_id) WHERE reviewer_app_user_id IS NOT NULL AND deleted_at IS NULL,
  INDEX idx_organisation_review_organisation_id_published_at (organisation_id, published_at DESC) STORING (rating_overall, helpful_count) WHERE is_published AND deleted_at IS NULL,
  INDEX idx_organisation_review_moderation_status_id_created_at (moderation_status_id, created_at) USING HASH WITH (bucket_count = 8) WHERE deleted_at IS NULL,
  INDEX idx_organisation_review_reviewer_app_user_id (reviewer_app_user_id) WHERE reviewer_app_user_id IS NOT NULL,
  INDEX idx_organisation_review_reviewer_relation_id (reviewer_relation_id),
  INDEX idx_organisation_review_employment_type_id (employment_type_id),
  INDEX idx_organisation_review_job_role_id (job_role_id),
  INDEX idx_organisation_review_recommendation_answer_id (recommendation_answer_id),
  INDEX idx_organisation_review_language_id (language_id)
);
-- @@
