CREATE TABLE IF NOT EXISTS organisation_verification (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  organisation_id UUID NOT NULL,
  organisation_identifier_id UUID,
  verification_kind_id UUID NOT NULL,
  verification_status_id UUID NOT NULL,
  vendor_code STRING(40) NOT NULL,
  vendor_reference STRING(120),
  idempotency_key STRING(100) NOT NULL,
  attempt_no INT2 NOT NULL DEFAULT 1,
  requested_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  checked_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ,
  retry_after_at TIMESTAMPTZ,
  registered_name_returned STRING(300),
  name_match_score DECIMAL(5,2),
  outcome_detail STRING(300),
  vendor_token STRING(200),
  requested_by_app_user_id UUID,
  CONSTRAINT pk_organisation_verification PRIMARY KEY (id),
  CONSTRAINT uq_organisation_verification_idempotency_key UNIQUE (idempotency_key),
  CONSTRAINT uq_organisation_verification_organisation_id_verification_kind_id_attempt_no UNIQUE (organisation_id, verification_kind_id, attempt_no),
  CONSTRAINT ck_organisation_verification_score_range CHECK (name_match_score IS NULL OR name_match_score BETWEEN 0 AND 100),
  CONSTRAINT ck_organisation_verification_checked_after_requested CHECK (checked_at IS NULL OR checked_at >= requested_at),
  CONSTRAINT ck_organisation_verification_expires_after_checked CHECK (expires_at IS NULL OR checked_at IS NULL OR expires_at >= checked_at),
  CONSTRAINT fk_organisation_verification_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_verification_identifier_same_org FOREIGN KEY (organisation_identifier_id, organisation_id) REFERENCES organisation_identifier (id, organisation_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_verification_verification_kind_id FOREIGN KEY (verification_kind_id) REFERENCES verification_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_verification_verification_status_id FOREIGN KEY (verification_status_id) REFERENCES verification_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_organisation_verification_organisation_id_verification_kind_id_requested_at (organisation_id, verification_kind_id, requested_at DESC),
  INDEX idx_organisation_verification_expires_at (expires_at) WHERE expires_at IS NOT NULL,
  UNIQUE INDEX uq_organisation_verification_vendor_code_vendor_reference (vendor_code, vendor_reference) WHERE vendor_reference IS NOT NULL,
  INDEX idx_organisation_verification_organisation_identifier_id (organisation_identifier_id),
  INDEX idx_organisation_verification_verification_kind_id (verification_kind_id),
  INDEX idx_organisation_verification_verification_status_id (verification_status_id),
  INDEX idx_organisation_verification_requested_by_app_user_id (requested_by_app_user_id)
);
