CREATE TABLE IF NOT EXISTS recruiter_organisation_mapping (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  recruiter_app_user_id UUID NOT NULL,
  organisation_id UUID NOT NULL,
  mapping_scope_id UUID NOT NULL,
  sequence_no INT4 NOT NULL,
  prior_recruiter_organisation_mapping_id UUID,
  prior_ended_at TIMESTAMPTZ,
  effective_from TIMESTAMPTZ NOT NULL DEFAULT now(),
  effective_to TIMESTAMPTZ,
  mapping_end_reason_id UUID,
  approved_by_app_user_id UUID,
  CONSTRAINT pk_recruiter_organisation_mapping PRIMARY KEY (id),
  CONSTRAINT uq_recruiter_organisation_mapping_chain_target UNIQUE (id, recruiter_app_user_id, organisation_id, effective_to),
  CONSTRAINT uq_recruiter_organisation_mapping_prior_recruiter_organisation_mapping_id UNIQUE (prior_recruiter_organisation_mapping_id),
  CONSTRAINT uq_recruiter_organisation_mapping_recruiter_app_user_id_organisation_id_sequence_no UNIQUE (recruiter_app_user_id, organisation_id, sequence_no),
  CONSTRAINT ck_recruiter_organisation_mapping_effective_range CHECK (effective_to IS NULL OR effective_to > effective_from),
  CONSTRAINT ck_recruiter_organisation_mapping_chain_nulls CHECK ((prior_recruiter_organisation_mapping_id IS NULL) = (prior_ended_at IS NULL) AND (prior_recruiter_organisation_mapping_id IS NULL) = (sequence_no = 1)),
  CONSTRAINT ck_recruiter_organisation_mapping_starts_after_prior CHECK (prior_ended_at IS NULL OR effective_from >= prior_ended_at),
  CONSTRAINT ck_recruiter_organisation_mapping_end_reason_pair CHECK ((effective_to IS NULL) = (mapping_end_reason_id IS NULL)),
  CONSTRAINT fk_recruiter_organisation_mapping_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_recruiter_organisation_mapping_mapping_scope_id FOREIGN KEY (mapping_scope_id) REFERENCES mapping_scope (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_recruiter_organisation_mapping_mapping_end_reason_id FOREIGN KEY (mapping_end_reason_id) REFERENCES mapping_end_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_recruiter_organisation_mapping_prior_chain FOREIGN KEY (prior_recruiter_organisation_mapping_id, recruiter_app_user_id, organisation_id, prior_ended_at) REFERENCES recruiter_organisation_mapping (id, recruiter_app_user_id, organisation_id, effective_to) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_recruiter_organisation_mapping_recruiter_app_user_id_organisation_id_open (recruiter_app_user_id, organisation_id) WHERE effective_to IS NULL,
  UNIQUE INDEX uq_recruiter_organisation_mapping_recruiter_app_user_id_organisation_id_first (recruiter_app_user_id, organisation_id) WHERE prior_recruiter_organisation_mapping_id IS NULL,
  INDEX idx_recruiter_organisation_mapping_organisation_id_recruiter_app_user_id (organisation_id, recruiter_app_user_id) STORING (mapping_scope_id, effective_from) WHERE effective_to IS NULL,
  INDEX idx_recruiter_organisation_mapping_recruiter_app_user_id_effective_from (recruiter_app_user_id, effective_from DESC),
  INDEX idx_recruiter_organisation_mapping_mapping_scope_id (mapping_scope_id),
  INDEX idx_recruiter_organisation_mapping_mapping_end_reason_id (mapping_end_reason_id),
  INDEX idx_recruiter_organisation_mapping_approved_by_app_user_id (approved_by_app_user_id)
);
