CREATE TABLE IF NOT EXISTS account (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  account_code STRING(40) NOT NULL,
  account_name STRING(200) NOT NULL,
  account_status_id UUID NOT NULL,
  primary_organisation_id UUID,
  account_manager_app_user_id UUID,
  billing_currency_id UUID NOT NULL,
  tax_residence_country_id UUID NOT NULL,
  payment_term_id UUID NOT NULL,
  is_prepaid BOOL NOT NULL DEFAULT true,
  credit_limit DECIMAL(18,4),
  billing_organisation_location_id UUID,
  billing_email STRING(254),
  billing_contact_name STRING(150),
  dunning_hold BOOL NOT NULL DEFAULT false,
  active_admin_count INT4 NOT NULL DEFAULT 0,
  activated_at TIMESTAMPTZ,
  suspended_at TIMESTAMPTZ,
  closed_at TIMESTAMPTZ,
  external_billing_ref STRING(100),
  CONSTRAINT pk_account PRIMARY KEY (id),
  CONSTRAINT ck_account_credit_limit_nonneg CHECK (credit_limit IS NULL OR credit_limit >= 0),
  CONSTRAINT ck_account_prepaid_no_credit CHECK (NOT is_prepaid OR credit_limit IS NULL),
  CONSTRAINT ck_account_billing_email_lower CHECK (billing_email IS NULL OR billing_email = lower(billing_email)),
  CONSTRAINT ck_account_admin_count_nonneg CHECK (active_admin_count >= 0),
  CONSTRAINT ck_account_operational_needs_admin CHECK (activated_at IS NULL OR closed_at IS NOT NULL OR active_admin_count >= 1),
  CONSTRAINT ck_account_closed_after_activated CHECK (closed_at IS NULL OR activated_at IS NULL OR closed_at >= activated_at),
  CONSTRAINT fk_account_account_status_id FOREIGN KEY (account_status_id) REFERENCES account_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_account_primary_organisation_id FOREIGN KEY (primary_organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_account_billing_currency_id FOREIGN KEY (billing_currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_account_tax_residence_country_id FOREIGN KEY (tax_residence_country_id) REFERENCES country (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_account_payment_term_id FOREIGN KEY (payment_term_id) REFERENCES payment_term (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_account_billing_organisation_location_id FOREIGN KEY (billing_organisation_location_id) REFERENCES organisation_location (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  UNIQUE INDEX uq_account_account_code (account_code) WHERE deleted_at IS NULL,
  INDEX idx_account_account_status_id_account_manager_app_user_id (account_status_id, account_manager_app_user_id) WHERE deleted_at IS NULL,
  UNIQUE INDEX uq_account_external_billing_ref (external_billing_ref) WHERE external_billing_ref IS NOT NULL AND deleted_at IS NULL,
  INDEX idx_account_primary_organisation_id (primary_organisation_id),
  INDEX idx_account_account_manager_app_user_id (account_manager_app_user_id),
  INDEX idx_account_billing_currency_id (billing_currency_id),
  INDEX idx_account_tax_residence_country_id (tax_residence_country_id),
  INDEX idx_account_payment_term_id (payment_term_id),
  INDEX idx_account_billing_organisation_location_id (billing_organisation_location_id)
);
-- @@
CREATE TABLE IF NOT EXISTS account_admin (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  account_id UUID NOT NULL,
  admin_app_user_id UUID NOT NULL,
  account_admin_level_id UUID NOT NULL,
  is_primary_contact BOOL NOT NULL DEFAULT false,
  effective_from TIMESTAMPTZ NOT NULL DEFAULT now(),
  effective_to TIMESTAMPTZ,
  revocation_reason STRING(200),
  CONSTRAINT pk_account_admin PRIMARY KEY (id),
  CONSTRAINT ck_account_admin_effective_range CHECK (effective_to IS NULL OR effective_to >= effective_from),
  CONSTRAINT ck_account_admin_revocation_pair CHECK ((effective_to IS NULL) = (revocation_reason IS NULL OR effective_to IS NULL)),
  CONSTRAINT fk_account_admin_account_id FOREIGN KEY (account_id) REFERENCES account (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_account_admin_account_admin_level_id FOREIGN KEY (account_admin_level_id) REFERENCES account_admin_level (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_account_admin_account_id_admin_app_user_id (account_id, admin_app_user_id) WHERE effective_to IS NULL,
  UNIQUE INDEX uq_account_admin_account_id_primary (account_id) WHERE is_primary_contact AND effective_to IS NULL,
  INDEX idx_account_admin_admin_app_user_id_open (admin_app_user_id) WHERE effective_to IS NULL,
  INDEX idx_account_admin_account_admin_level_id (account_admin_level_id)
);
