CREATE TABLE IF NOT EXISTS account_organisation (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  account_id UUID NOT NULL,
  organisation_id UUID NOT NULL,
  is_billing_owner BOOL NOT NULL DEFAULT false,
  effective_from TIMESTAMPTZ NOT NULL DEFAULT now(),
  effective_to TIMESTAMPTZ,
  end_note STRING(200),
  CONSTRAINT pk_account_organisation PRIMARY KEY (id),
  CONSTRAINT ck_account_organisation_effective_range CHECK (effective_to IS NULL OR effective_to >= effective_from),
  CONSTRAINT uq_account_organisation_account_id_organisation_id_effective_from UNIQUE (account_id, organisation_id, effective_from),
  CONSTRAINT fk_account_organisation_account_id FOREIGN KEY (account_id) REFERENCES account (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_account_organisation_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_account_organisation_organisation_id (organisation_id) WHERE effective_to IS NULL,
  INDEX idx_account_organisation_account_id_open (account_id) WHERE effective_to IS NULL,
  UNIQUE INDEX uq_account_organisation_account_id_billing_owner (account_id) WHERE is_billing_owner AND effective_to IS NULL
);
