CREATE TABLE IF NOT EXISTS account_setting (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  account_id UUID NOT NULL,
  account_setting_key_id UUID NOT NULL,
  setting_value JSONB NOT NULL,
  effective_from TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT pk_account_setting PRIMARY KEY (id),
  CONSTRAINT fk_account_setting_account_id FOREIGN KEY (account_id) REFERENCES account (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_account_setting_account_setting_key_id FOREIGN KEY (account_setting_key_id) REFERENCES account_setting_key (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_account_setting_account_id_account_setting_key_id (account_id, account_setting_key_id) WHERE deleted_at IS NULL,
  INDEX idx_account_setting_account_setting_key_id (account_setting_key_id)
);
