CREATE TABLE IF NOT EXISTS account_status_history (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  account_id UUID NOT NULL,
  from_account_status_id UUID,
  to_account_status_id UUID NOT NULL,
  effective_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  reason STRING(300),
  actor_app_user_id UUID,
  CONSTRAINT pk_account_status_history PRIMARY KEY (id),
  CONSTRAINT fk_account_status_history_account_id FOREIGN KEY (account_id) REFERENCES account (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_account_status_history_from_account_status_id FOREIGN KEY (from_account_status_id) REFERENCES account_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_account_status_history_to_account_status_id FOREIGN KEY (to_account_status_id) REFERENCES account_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_account_status_history_account_id_effective_at (account_id, effective_at DESC),
  INDEX idx_account_status_history_from_account_status_id (from_account_status_id),
  INDEX idx_account_status_history_to_account_status_id (to_account_status_id),
  INDEX idx_account_status_history_actor_app_user_id (actor_app_user_id)
);
