CREATE TABLE IF NOT EXISTS client_relationship (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  agency_organisation_id UUID NOT NULL,
  client_organisation_id UUID NOT NULL,
  client_relationship_status_id UUID NOT NULL,
  contract_reference STRING(100),
  effective_from TIMESTAMPTZ NOT NULL DEFAULT now(),
  effective_to TIMESTAMPTZ,
  fee_model_id UUID,
  fee_percent DECIMAL(5,2),
  margin_percent DECIMAL(5,2),
  payment_term_id UUID,
  guarantee_days INT2,
  is_exclusive BOOL NOT NULL DEFAULT false,
  CONSTRAINT pk_client_relationship PRIMARY KEY (id),
  CONSTRAINT ck_client_relationship_distinct_parties CHECK (agency_organisation_id <> client_organisation_id),
  CONSTRAINT ck_client_relationship_effective_range CHECK (effective_to IS NULL OR effective_to >= effective_from),
  CONSTRAINT ck_client_relationship_fee_percent_range CHECK (fee_percent IS NULL OR fee_percent BETWEEN 0 AND 100),
  CONSTRAINT ck_client_relationship_margin_percent_range CHECK (margin_percent IS NULL OR margin_percent BETWEEN 0 AND 100),
  CONSTRAINT ck_client_relationship_guarantee_range CHECK (guarantee_days IS NULL OR guarantee_days BETWEEN 0 AND 730),
  CONSTRAINT fk_client_relationship_agency_organisation_id FOREIGN KEY (agency_organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_client_relationship_client_organisation_id FOREIGN KEY (client_organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_client_relationship_client_relationship_status_id FOREIGN KEY (client_relationship_status_id) REFERENCES client_relationship_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_client_relationship_fee_model_id FOREIGN KEY (fee_model_id) REFERENCES fee_model (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_client_relationship_payment_term_id FOREIGN KEY (payment_term_id) REFERENCES payment_term (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_client_relationship_agency_organisation_id_client_organisation_id (agency_organisation_id, client_organisation_id) WHERE effective_to IS NULL AND deleted_at IS NULL,
  INDEX idx_client_relationship_client_organisation_id_effective_to (client_organisation_id, effective_to) WHERE deleted_at IS NULL,
  INDEX idx_client_relationship_client_relationship_status_id (client_relationship_status_id),
  INDEX idx_client_relationship_fee_model_id (fee_model_id),
  INDEX idx_client_relationship_payment_term_id (payment_term_id)
);
-- @@
CREATE TABLE IF NOT EXISTS organisation_department (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  organisation_id UUID NOT NULL,
  parent_organisation_department_id UUID,
  department_level INT2 NOT NULL,
  parent_level INT2,
  department_kind_id UUID NOT NULL,
  department_name STRING(150) NOT NULL,
  cost_centre_code STRING(30),
  organisation_location_id UUID,
  is_active BOOL NOT NULL DEFAULT true,
  CONSTRAINT pk_organisation_department PRIMARY KEY (id),
  CONSTRAINT uq_organisation_department_organisation_id_id_department_level UNIQUE (organisation_id, id, department_level),
  CONSTRAINT uq_organisation_department_organisation_id_id UNIQUE (organisation_id, id),
  CONSTRAINT ck_organisation_department_level_range CHECK (department_level BETWEEN 0 AND 5),
  CONSTRAINT ck_organisation_department_parent_chain_nulls CHECK ((parent_organisation_department_id IS NULL) = (parent_level IS NULL) AND (parent_level IS NULL) = (department_level = 0)),
  CONSTRAINT ck_organisation_department_level_increments CHECK (parent_level IS NULL OR department_level = parent_level + 1),
  CONSTRAINT fk_organisation_department_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_department_department_kind_id FOREIGN KEY (department_kind_id) REFERENCES department_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_department_parent_chain FOREIGN KEY (organisation_id, parent_organisation_department_id, parent_level) REFERENCES organisation_department (organisation_id, id, department_level) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_department_location_same_org FOREIGN KEY (organisation_id, organisation_location_id) REFERENCES organisation_location (organisation_id, id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_organisation_department_organisation_id_department_name (organisation_id, department_name) WHERE deleted_at IS NULL,
  INDEX idx_organisation_department_department_kind_id (department_kind_id)
);
-- @@
CREATE TABLE IF NOT EXISTS organisation_invitation (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  organisation_id UUID NOT NULL,
  invited_email STRING(254) NOT NULL,
  invitation_status_id UUID NOT NULL,
  mapping_scope_id UUID NOT NULL,
  token_hash STRING(100) NOT NULL,
  invited_by_app_user_id UUID NOT NULL,
  invitee_app_user_id UUID,
  recruiter_organisation_mapping_id UUID,
  resend_count INT2 NOT NULL DEFAULT 0,
  expires_at TIMESTAMPTZ NOT NULL,
  accepted_at TIMESTAMPTZ,
  revoked_at TIMESTAMPTZ,
  CONSTRAINT pk_organisation_invitation PRIMARY KEY (id),
  CONSTRAINT uq_organisation_invitation_token_hash UNIQUE (token_hash),
  CONSTRAINT ck_organisation_invitation_invited_email_lower CHECK (invited_email = lower(invited_email)),
  CONSTRAINT ck_organisation_invitation_single_outcome CHECK (accepted_at IS NULL OR revoked_at IS NULL),
  CONSTRAINT ck_organisation_invitation_resend_range CHECK (resend_count BETWEEN 0 AND 10),
  CONSTRAINT fk_organisation_invitation_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_invitation_invitation_status_id FOREIGN KEY (invitation_status_id) REFERENCES invitation_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_invitation_mapping_scope_id FOREIGN KEY (mapping_scope_id) REFERENCES mapping_scope (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_invitation_recruiter_organisation_mapping_id FOREIGN KEY (recruiter_organisation_mapping_id) REFERENCES recruiter_organisation_mapping (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  UNIQUE INDEX uq_organisation_invitation_organisation_id_invited_email (organisation_id, invited_email) WHERE accepted_at IS NULL AND revoked_at IS NULL,
  INDEX idx_organisation_invitation_invited_email (invited_email) WHERE accepted_at IS NULL AND revoked_at IS NULL,
  INDEX idx_organisation_invitation_invitation_status_id (invitation_status_id),
  INDEX idx_organisation_invitation_mapping_scope_id (mapping_scope_id),
  INDEX idx_organisation_invitation_invited_by_app_user_id (invited_by_app_user_id),
  INDEX idx_organisation_invitation_invitee_app_user_id (invitee_app_user_id),
  INDEX idx_organisation_invitation_recruiter_organisation_mapping_id (recruiter_organisation_mapping_id)
) WITH (ttl_expiration_expression = '(expires_at + INTERVAL ''180 days'')', ttl_job_cron = '@daily');
